// Пагинация: получаем страницы 2..6 с паузой 400 мс и лимитами
const LIMIT = 100;
const MAX_PAGES = 6;
const BASE = 'https://jsonplaceholder.typicode.com/comments';
const UA = 'StudentScraperBot/1.0 (+https://github.com/PINNOS/parsing)';

const collected = [];
for (const item of $input.all()) {
  if (item.json && item.json.id !== undefined) collected.push(item.json);
}

let page = 2;
while (page <= MAX_PAGES) {
  let resp = null;
  let attempt = 0;
  while (true) {
    attempt++;
    try {
      resp = await this.helpers.httpRequest({
        url: BASE + '?_page=' + page + '&_limit=' + LIMIT,
        method: 'GET',
        json: true,
        timeout: 20000,
        headers: { 'User-Agent': UA, Accept: 'application/json' }
      });
      break;
    } catch (e) {
      const status = (e && (e.statusCode || e.httpCode || e.response?.status)) || 0;
      const retryable = status === 429 || status >= 500 || status === 0;
      if (!retryable || attempt >= 4) throw e;
      const delay = Math.min(8000, 500 * Math.pow(2, attempt - 1));
      await new Promise((r) => setTimeout(r, delay * (0.5 + Math.random() * 0.5)));
    }
  }
  if (!Array.isArray(resp) || resp.length === 0) break;
  for (const r of resp) collected.push(r);
  if (resp.length < LIMIT) break;
  page++;
  await new Promise((r) => setTimeout(r, 400));
}

if (collected.length < 300) {
  throw new Error('Собрано меньше 300 записей: ' + collected.length);
}
return collected.map((r) => ({ json: r }));

// Нормализация полей (переименование, типизация, вычисляемые) и дедупликация по comment_id
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  if (!r || r.id === undefined) continue;
  const id = Number(r.id);
  if (seen.has(id)) continue;
  seen.add(id);
  const email = String(r.email || '');
  const at = email.indexOf('@');
  const masked = at > 1 ? email[0] + '***' + email.slice(at) : email;
  out.push({
    json: {
      comment_id: id,
      post_id: Number(r.postId),
      author_email_masked: masked,
      comment_len: String(r.body || '').length,
      collected_at: new Date().toISOString()
    }
  });
}
if (out.length === 0) throw new Error('После нормализации не осталось валидных записей');
return out;

// Выгрузка: собираем CSV и отдаём бинарный файл
const rows = $input.all().map((i) => i.json);
if (rows.length === 0) throw new Error('Нет данных для выгрузки CSV');
const headers = Object.keys(rows[0]);
const esc = (v) => '"' + String(v === null || v === undefined ? '' : v).replace(/"/g, '""') + '"';
const csv = [headers.join(',')]
  .concat(rows.map((r) => headers.map((h) => esc(r[h])).join(',')))
  .join('\n');
return [{
  json: { rows: rows.length, columns: headers.length, file: 'nocode_result.csv' },
  binary: {
    data: {
      data: Buffer.from(csv, 'utf8').toString('base64'),
      mimeType: 'text/csv',
      fileName: 'nocode_result.csv'
    }
  }
}];

// Ветка ошибки: фиксируем инцидент сбора
return $input.all().map((i) => ({
  json: {
    ts: new Date().toISOString(),
    source: 'jsonplaceholder.comments',
    status: 'error',
    detail: JSON.stringify(i.json || {}).slice(0, 300)
  }
}));

// Формируем CSV-файл журнала ошибок
const rows = $input.all().map((i) => i.json);
const headers = ['ts', 'source', 'status', 'detail'];
const esc = (v) => '"' + String(v === null || v === undefined ? '' : v).replace(/"/g, '""') + '"';
const csv = [headers.join(',')]
  .concat(rows.map((r) => headers.map((h) => esc(r[h])).join(',')))
  .join('\n');
return [{
  json: { rows: rows.length },
  binary: {
    data: {
      data: Buffer.from(csv, 'utf8').toString('base64'),
      mimeType: 'text/csv',
      fileName: 'nocode_errors.csv'
    }
  }
}];
